#!/usr/bin/env bash
# ZONO — apply לידים (server-paginated command table). macOS-safe base64 decode.
set -euo pipefail
cd "$(dirname "$0")"
echo "→ repo: $(pwd)"
git am --abort 2>/dev/null || true
git fetch origin
git checkout main
git reset --hard origin/main
cat > /tmp/zono-leads.patch.b64 <<'B64EOF'

B64EOF
base64 -d < /tmp/zono-leads.patch.b64 > /tmp/zono-leads.patch
git am --3way /tmp/zono-leads.patch
echo "→ commit applied:"; git log --oneline -2
git push origin main
echo "✓ pushed. Redeploy will pick up /leads."
